-- 1. SEED CLUSTERS
INSERT INTO clusters (id, name, description, color) VALUES
('11111111-1111-1111-1111-111111111111', 'Wisata Bahari, Pesisir & Pantai', 'Destinasi wisata yang berhubungan dengan pantai, laut, dan aktivitas pesisir di Kota Balikpapan.', '#0ea5e9'),
('22222222-2222-2222-2222-222222222222', 'Wisata Alam, Konservasi & Edukasi', 'Destinasi wisata hutan, waduk, kebun raya, dan pusat konservasi keanekaragaman hayati.', '#22c55e'),
('33333333-3333-3333-3333-333333333333', 'Wisata Sejarah, Budaya & Heritage', 'Kawasan cagar budaya, kampung sejarah, sumur minyak tua, dan museum kebudayaan.', '#f59e0b'),
('44444444-4444-4444-4444-444444444444', 'Wisata Kreatif, Kuliner & Belanja', 'Pusat perbelanjaan kerajinan khas, pasar tradisional, batik, dan sentra kuliner Balikpapan.', '#8b5cf6'),
('55555555-5555-5555-5555-555555555555', 'Wisata MICE & Bisnis', 'Gedung pertemuan besar, taman hiburan indoor, pelabuhan penyeberangan, bandara, dan kawasan ekonomi.', '#ef4444')
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, color = EXCLUDED.color;

-- 2. SEED CRITERIA
INSERT INTO criteria (id, code, name, type, description, weight, sort_order) VALUES
('a1111111-1111-1111-1111-111111111111', 'K1', 'Aksesibilitas', 'benefit', 'Kemudahan akses, kondisi jalan, transportasi umum, dan rambu penunjuk arah menuju lokasi.', 0.0, 1),
('a2222222-2222-2222-2222-222222222222', 'K2', 'Amenitas', 'benefit', 'Ketersediaan fasilitas penunjang seperti toilet, tempat ibadah, tempat parkir, warung makan, dan penginapan.', 0.0, 2),
('a3333333-3333-3333-3333-333333333333', 'K3', 'Atraksi', 'benefit', 'Keunikan objek wisata, daya tarik utama, keindahan alam, kegiatan rekreasi, dan pagelaran seni.', 0.0, 3),
('a4444444-4444-4444-4444-444444444444', 'K4', 'Kelembagaan', 'benefit', 'Adanya pengelola resmi, keterlibatan pokdarwis (kelompok sadar wisata), pemandu wisata, serta dukungan regulasi.', 0.0, 4),
('a5555555-5555-5555-5555-555555555555', 'K5', 'Dampak Ekonomi', 'benefit', 'Kontribusi terhadap pendapatan asli daerah (PAD), peluang usaha bagi masyarakat sekitar, dan penyerapan tenaga kerja.', 0.0, 5),
('a6666666-6666-6666-6666-666666666666', 'K6', 'Kelestarian Lingk.', 'benefit', 'Upaya pelestarian alam, kebersihan lingkungan, pengelolaan sampah, dan pencegahan kerusakan ekosistem.', 0.0, 6),
('a7777777-7777-7777-7777-777777777777', 'K7', 'Relevansi IKN', 'benefit', 'Keterkaitan dan kesiapan destinasi dalam menyangga serta melayani kebutuhan pariwisata untuk Ibu Kota Nusantara.', 0.0, 7)
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, type = EXCLUDED.type, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order;

